const i18n = (() => {
  const KEY = 'faketvijaLanguage';
  const DEFAULT = 'lv';
  const SUPPORTED = ['lv', 'en'];
  let memory = null;  // in-memory fallback when storage is unavailable
  const read = () => {
    try { const value = localStorage.getItem(KEY); if (SUPPORTED.includes(value)) return value; } catch {}
    return memory;
  };
  const write = value => {
    memory = value;
    try { localStorage.setItem(KEY, value); } catch {}
  };
  let language = read() || DEFAULT;
  document.documentElement.lang = language;
  let pendingStyle = null;
  if (language !== DEFAULT && document.head) {
    pendingStyle = document.createElement('style');
    pendingStyle.textContent = 'body{visibility:hidden}';
    document.head.append(pendingStyle);
  }
  const originalText = new WeakMap();
  const originalAttributes = new WeakMap();
  const originalTitle = document.title;
  const listeners = new Set();

  const interpolate = (text, params) => text.replace(/\{(\w+)\}/g, (match, name) => (params && name in params ? String(params[name]) : match));
  function t(key, params) {
    const table = MESSAGES[language] || MESSAGES[DEFAULT];
    const text = table[key] ?? MESSAGES[DEFAULT][key] ?? key;
    return params ? interpolate(text, params) : text;
  }
  const locale = () => (language === 'en' ? 'en-GB' : 'lv-LV');
  function formatDate(value, options) {
    if (!value) return '—';
    const parsed = value instanceof Date ? value : new Date(String(value).length === 10 ? value + 'T00:00:00' : value);
    if (Number.isNaN(parsed.getTime())) return String(value);
    return parsed.toLocaleDateString(locale(), options || {day: '2-digit', month: '2-digit', year: 'numeric'});
  }
  const formatNumber = (value, options) => new Intl.NumberFormat(locale(), options).format(value);
  const formatMoney = value => formatNumber(value, {style: 'currency', currency: 'EUR', maximumFractionDigits: 2});
  const formatMonth = key => { const [year, month] = String(key).split('-'); return language === 'en' ? `${month}/${year}` : `${month}.${year}`; };

  function applyKeyed(root) {
    root.querySelectorAll('[data-i18n]').forEach(element => {
      let params = null;
      if (element.dataset.i18nParams) { try { params = JSON.parse(element.dataset.i18nParams); } catch {} }
      element.textContent = t(element.dataset.i18n, params);
    });
    root.querySelectorAll('[data-i18n-attr]').forEach(element => {
      for (const pair of element.dataset.i18nAttr.split(',')) {
        const [name, key] = pair.split(':').map(part => part.trim());
        if (name && key) element.setAttribute(name, t(key));
      }
    });
  }
  function applyLegacy(root) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      if (node.parentElement.closest('script,style,[data-language-label],[data-no-translate],[data-i18n]')) continue;
      if (!originalText.has(node)) originalText.set(node, node.nodeValue);
      const source = originalText.get(node);
      const translation = englishTranslations[source.trim()];
      node.nodeValue = language === 'en' && translation ? source.replace(source.trim(), translation) : source;
    }
    root.querySelectorAll('[aria-label],[placeholder],[alt]').forEach(element => {
      if (element.hasAttribute('data-i18n-attr')) return;
      if (!originalAttributes.has(element)) originalAttributes.set(element, Object.fromEntries(['aria-label', 'placeholder', 'alt'].filter(name => element.hasAttribute(name)).map(name => [name, element.getAttribute(name)])));
      for (const [name, value] of Object.entries(originalAttributes.get(element))) element.setAttribute(name, language === 'en' ? englishTranslations[value] || value : value);
    });
  }
  function apply(root) {
    if (!document.body) return;
    const scope = root || document.body;
    document.documentElement.lang = language;
    applyKeyed(scope);
    applyLegacy(scope);
    if (!root) {
      const titleKey = document.documentElement.dataset.i18nTitle;
      document.title = titleKey ? t(titleKey) : (language === 'en' ? englishTranslations[originalTitle] || originalTitle : originalTitle);
      document.querySelectorAll('[data-language-toggle]').forEach(button => {
        const label = button.querySelector('[data-language-label]');
        if (label) label.textContent = button.classList.contains('language') ? t('lang.toggleLong') : t('lang.toggle');
        button.setAttribute('aria-label', t('lang.switchTo'));
      });
    }
    if (pendingStyle) { pendingStyle.remove(); pendingStyle = null; }
  }
  function set(value, {persist = true} = {}) {
    if (!SUPPORTED.includes(value)) value = DEFAULT;
    const changed = value !== language;
    language = value;
    if (persist) write(value);
    apply();
    if (changed) {
      for (const listener of listeners) { try { listener(language); } catch {} }
      document.dispatchEvent(new CustomEvent('faketvija:language', {detail: {language}}));
    }
  }
  window.addEventListener('storage', event => {
    if (event.key === KEY && SUPPORTED.includes(event.newValue) && event.newValue !== language) set(event.newValue, {persist: false});
  });
  document.addEventListener('DOMContentLoaded', () => {
    apply();
    document.querySelectorAll('[data-language-toggle]').forEach(button => button.addEventListener('click', () => set(language === 'lv' ? 'en' : 'lv')));
  });
  return {
    get language() { return language; }, set, t, apply, formatDate, formatNumber, formatMoney, formatMonth, locale,
    onChange: listener => { listeners.add(listener); return () => listeners.delete(listener); },
    key: KEY, default: DEFAULT, supported: SUPPORTED,
  };
})();
window.i18n = i18n;
// Compatibility helpers used by older scripts.
function applyLanguage(root) { i18n.apply(root); }
function setTranslatedStatus(element, latvian, key, params) {
  if (!element) return;
  if (key) { element.dataset.i18n = key; element.dataset.i18nParams = params ? JSON.stringify(params) : ''; element.textContent = i18n.t(key, params); return; }
  delete element.dataset.i18n;
  element.textContent = latvian;
  i18n.apply(element.parentElement || element);
}
function t(key, params) { return i18n.t(key, params); }
